// CubeGame.Features.World.Foundation — G2-J: explicit world generation identity and save-compatibility rule.
//
// The rule of the project: a world that the player did not change is restored from seed; player changes live
// separately (WorldDeltaStore / .world). Therefore the generation ALGORITHM is part of the save identity, not an
// implementation detail. A save written by one generator must never be silently regenerated by another one.
//
// Before G2 the identity was the generator id string alone (AlphaTerrainGenerator.WorldRuntimeId = ".../9").
// That still works, but it does not notice a change of the *data* that the generator consumes (biome table,
// vegetation rules, structure rules). G2 adds a second marker: a fingerprint of the generation profile, written
// into the world file as an optional field. Old files (no fingerprint) load as `LegacyWorld`.
//
// Changing any of the version constants below changes the fingerprint of every new world and makes existing
// worlds report `ProfileChanged` instead of loading into a silently different world.
using System;
using System.Collections.Generic;
using System.Globalization;
using CubeGame.Core.Persistence;

namespace CubeGame.Features.World.Foundation
{
    /// <summary>
    /// Version of everything that decides what the world looks like. Bump a constant when the matching data or
    /// algorithm changes; never edit a released value in place.
    /// </summary>
    public static class WorldGenerationProfile
    {
        /// <summary>Terrain / zone / feature algorithms (the generator id already carries its own version).</summary>
        public const int AlgorithmVersion = 1;

        /// <summary>Climate sampling and climate axes (G2-B).</summary>
        public const int ClimateVersion = 1;

        /// <summary>Biome table: envelopes, surface/vegetation/spawn/structure references (G2-B).</summary>
        public const int BiomeCatalogVersion = 1;

        /// <summary>Vegetation rules: where plants are allowed (G2-E). Not the visual assets.</summary>
        public const int VegetationRuleVersion = 1;

        /// <summary>Structure rules: candidate → validation → placement (G2-F).</summary>
        public const int StructureRuleVersion = 1;

        /// <summary>Settlement / dungeon seams: reserved sites and anchors (G2-G).</summary>
        public const int SeamRuleVersion = 1;

        public const string Tag = "cubegame.world/v1";

        /// <summary>Statement of what this build promises to a save file.</summary>
        public static string Describe() =>
            $"{Tag};algorithm={AlgorithmVersion};climate={ClimateVersion};biomes={BiomeCatalogVersion};" +
            $"vegetation={VegetationRuleVersion};structures={StructureRuleVersion};seams={SeamRuleVersion}";

        /// <summary>Fingerprint of the generation profile (no seed): stable within one build, changes with the profile.</summary>
        public static ulong Hash()
        {
            return SaveService.Fnv1a64(Describe());
        }

        public static List<string> Validate()
        {
            var problems = new List<string>();
            // Local copies: comparing the constants directly makes the checks compile-time dead code.
            int algorithm = AlgorithmVersion;
            int climate = ClimateVersion;
            int biomes = BiomeCatalogVersion;
            int vegetation = VegetationRuleVersion;
            int structures = StructureRuleVersion;
            int seams = SeamRuleVersion;
            if (algorithm < 1) problems.Add("WORLD_PROFILE_ALGORITHM_VERSION");
            if (climate < 1) problems.Add("WORLD_PROFILE_CLIMATE_VERSION");
            if (biomes < 1) problems.Add("WORLD_PROFILE_BIOME_VERSION");
            if (vegetation < 1) problems.Add("WORLD_PROFILE_VEGETATION_VERSION");
            if (structures < 1) problems.Add("WORLD_PROFILE_STRUCTURE_VERSION");
            if (seams < 1) problems.Add("WORLD_PROFILE_SEAM_VERSION");
            string tag = Tag;
            if (string.IsNullOrEmpty(tag)) problems.Add("WORLD_PROFILE_TAG_EMPTY");
            if (Hash() == 0UL) problems.Add("WORLD_PROFILE_HASH_ZERO");
            return problems;
        }
    }

    /// <summary>Outcome of comparing a save's generation identity with the running generator.</summary>
    public enum WorldCompatibility
    {
        /// <summary>Same generator id, same fingerprint.</summary>
        Compatible = 0,

        /// <summary>Save predates fingerprints (G2): readable, the world is regenerated by the current profile.</summary>
        LegacyWorld = 1,

        /// <summary>Same generator id, different generation profile (data changed): must not load silently.</summary>
        ProfileChanged = 2,

        /// <summary>Different generator id/version.</summary>
        GeneratorChanged = 3,

        /// <summary>Fingerprint text is present but unreadable.</summary>
        Malformed = 4,
    }

    public readonly struct WorldCompatibilityReport
    {
        public WorldCompatibilityReport(WorldCompatibility status, bool canLoad, string reason)
        {
            Status = status;
            CanLoad = canLoad;
            Reason = reason ?? string.Empty;
        }

        public WorldCompatibility Status { get; }

        public bool CanLoad { get; }

        public string Reason { get; }

        public override string ToString() => $"{Status} canLoad={CanLoad} {Reason}";
    }

    /// <summary>
    /// Builds and checks the generation identity of a world. Pure functions: safe on worker threads, no Unity.
    /// </summary>
    public static class WorldGenerationIdentity
    {
        /// <summary>Fingerprint written by saves before G2 (field absent).</summary>
        public const string LegacyFingerprint = "";

        /// <summary>Generation version encoded in the generator id suffix, e.g. <c>cubegame.alpha_terrain/9</c> → 9.</summary>
        public static int VersionOf(string generatorId)
        {
            if (string.IsNullOrEmpty(generatorId)) return 0;
            int slash = generatorId.LastIndexOf('/');
            if (slash < 0 || slash == generatorId.Length - 1) return 0;
            return int.TryParse(generatorId.Substring(slash + 1), NumberStyles.Integer,
                CultureInfo.InvariantCulture, out int version) ? version : 0;
        }

        /// <summary>
        /// Fingerprint of (generator id, seed, generation profile). Same inputs → same text on every platform.
        /// </summary>
        public static string Fingerprint(string generatorId, uint seed)
        {
            string id = generatorId ?? string.Empty;
            string text = id + "|" + seed.ToString(CultureInfo.InvariantCulture) + "|" +
                          WorldGenerationProfile.Hash().ToString("x16", CultureInfo.InvariantCulture);
            return SaveService.Fnv1a64(text).ToString("x16", CultureInfo.InvariantCulture);
        }

        /// <summary>
        /// Compares the identity recorded by a save with the running generator. The world file is only readable
        /// when the generator id matches (that is the pre-G2 rule) and the profile did not change.
        /// </summary>
        public static WorldCompatibilityReport Check(string savedGeneratorId, uint savedSeed,
            string savedFingerprint, string runningGeneratorId, uint runningSeed)
        {
            if (!string.Equals(savedGeneratorId ?? string.Empty, runningGeneratorId ?? string.Empty,
                    StringComparison.Ordinal))
            {
                return new WorldCompatibilityReport(WorldCompatibility.GeneratorChanged, false,
                    $"world was generated by '{savedGeneratorId}', game runs '{runningGeneratorId}'");
            }

            if (savedSeed != runningSeed)
            {
                return new WorldCompatibilityReport(WorldCompatibility.GeneratorChanged, false,
                    $"world seed {savedSeed} differs from {runningSeed}");
            }

            if (string.IsNullOrEmpty(savedFingerprint))
            {
                return new WorldCompatibilityReport(WorldCompatibility.LegacyWorld, true,
                    "save predates the G2 generation fingerprint; regenerated by the current profile");
            }

            if (savedFingerprint.Length != 16)
            {
                return new WorldCompatibilityReport(WorldCompatibility.Malformed, false,
                    $"generation fingerprint '{savedFingerprint}' is not FNV-1a 64 hex");
            }

            string expected = Fingerprint(runningGeneratorId, runningSeed);
            if (!string.Equals(savedFingerprint, expected, StringComparison.Ordinal))
            {
                return new WorldCompatibilityReport(WorldCompatibility.ProfileChanged, false,
                    $"world generation profile changed: save {savedFingerprint}, game {expected} " +
                    $"({WorldGenerationProfile.Describe()})");
            }

            return new WorldCompatibilityReport(WorldCompatibility.Compatible, true, "generation identity matches");
        }

        public static string Describe(string generatorId, uint seed) =>
            $"gen={generatorId} v={VersionOf(generatorId)} seed={seed} fingerprint={Fingerprint(generatorId, seed)} " +
            WorldGenerationProfile.Describe();
    }
}
